      "content": "[build-system]\nrequires = [\n    \"setuptools>=61.0\",\n    \"setuptools-scm>=8.0\",\n    \"cmake>=3.15\",\n    \"maturin>=1.0,<2.0\",\n    \"wheel\",\n]\nbuild-backend = \"setuptools.build_meta\"\n\n[project]\nname = \"openviking\"\ndynamic = [\"version\", \"readme\"]\ndescription = \"An Agent-native context database\"\nrequires-python = \">=3.10\"\nauthors = [\n    {name = \"ByteDance\", email = \"noreply@bytedance.com\"}\n]\nlicense = \"AGPL-3.0\"\nclassifiers = [\n    \"Development Status :: 3 - Alpha\",\n    \"Intended Audience :: Developers\",\n    \"Topic :: Scientific/Engineering :: Artificial Intelligence\",\n    \"Programming Language :: Python :: 3\",\n    \"Programming Language :: Python :: 3.10\",\n    \"Programming Language :: Python :: 3.11\",\n    \"Programming Language :: Python :: 3.12\",\n    \"Programming Language :: Python :: 3.13\",\n    \"Programming Language :: Python :: 3.14\",\n]\ndependencies = [\n    \"aiohttp>=3.13.3\",\n    \"async-timeout>=5.0.1\",\n    \"orjson>=3.11.7\",\n    \"packaging>=24.0\",\n    \"openviking-sdk>=0.1.17\",\n    \"pydantic>=2.0.0\",\n    \"typing-extensions>=4.5.0\",\n    \"pyyaml>=6.0\",\n    \"httpx>=0.25.0\",\n    \"pdfplumber>=0.10.0\",\n    \"scrapy>=2.11.0\",\n    \"trafilatura>=1.12.0\",\n    \"feedparser>=6.0.0\",\n    \"defusedxml>=0.7.1\",\n    \"cairosvg>=2.9.1\",\n    \"openai>=1.0.0\",\n    \"requests>=2.33.0\",\n    \"charset-normalizer>=3.4,<4\",\n    \"firecrawl-anydoc>=0.2.4,<0.3\",\n    \"json-repair>=0.25.0\",\n    \"apscheduler>=3.11.0\",\n    \"volcengine>=1.0.216\",\n    \"volcengine-python-sdk[ark]>=5.0.3\",\n    \"fastapi>=0.128.0\",\n    \"uvicorn>=0.39.0\",\n    \"xxhash>=3.0.0\",\n    \"rapidfuzz>=3.14,<4\",\n    \"jinja2>=3.1.6\",\n    \"tabulate>=0.9.0\",\n    \"urllib3>=2.7.0\",\n    \"protobuf>=6.33.5\",\n    \"pdfminer-six>=20251230\",\n    \"typer>=0.12.0\",\n    \"litellm>=1.83.7,<1.91.2\",\n    \"python-multipart>=0.0.31\",\n    # Pin the parsing stack to avoid unvalidated upstream API and grammar changes.\n    \"tree-sitter==0.25.2\",\n    \"tree-sitter-python==0.25.0\",\n    \"tree-sitter-javascript==0.25.0\",\n    \"tree-sitter-typescript==0.23.2\",\n    \"tree-sitter-java==0.23.5\",\n    \"tree-sitter-cpp==0.23.4\",\n    \"tree-sitter-rust==0.24.0\",\n    \"tree-sitter-go==0.25.0\",\n    \"tree-sitter-c-sharp==0.23.1\",\n    \"tree-sitter-php==0.24.1\",\n    \"tree-sitter-lua==0.5.0\",\n    # OpenTelemetry\n    \"prometheus-client>=0.24,<1\",\n    \"opentelemetry-api>=1.40,<2\",\n    \"opentelemetry-sdk>=1.40,<2\",\n    \"opentelemetry-exporter-otlp-proto-grpc>=1.40,<2\",\n    \"opentelemetry-exporter-otlp-proto-http>=1.40,<2\",\n    \"opentelemetry-instrumentation-asyncio>=0.61b0\",\n    \"loguru>=0.7.3\",\n    \"cryptography>=48.0.1\",\n    \"argon2-cffi>=23.0.0\",\n    \"lark-oapi>=1.5.3\",\n    \"mcp>=1.27,<2\",\n    \"pathspec>=1.1.1\",\n    \"grep-ast==0.9.0\",\n    \"tree-sitter-language-pack==1.13.3\",\n]\n\n\n[project.optional-dependencies]\nexpiry = [\n  \"redis>=5.3.1,<7\",\n]\ngateway-fast = [\n    \"uvloop>=0.21; sys_platform != 'win32'\",\n    \"httptools>=0.6\",\n]\nmysql = [\n    \"aiomysql>=0.2.0,<1\",\n    \"PyMySQL>=1.1,<1.2\",\n    \"SQLAlchemy[asyncio]>=2.0.54,<2.1\",\n]\nredis-mysql = [\n  \"aiomysql>=0.2.0,<1\",\n  \"redis>=5.3.1,<7\",\n  \"SQLAlchemy[asyncio]>=2.0.54,<2.1\",\n]\ntest = [\n  \"SQLAlchemy[asyncio]>=2.0,<2.1\",\n  \"redis>=5.3.1,<7\",\n  \"pytest>=7.0.0\",\n  \"pytest-asyncio>=0.21.0\",\n  \"pytest-xdist>=3.5.0\",\n  \"boto3>=1.42.44\",\n  \"pytest-cov>=4.0.0\",\n  \"ragas>=0.1.0\",\n  \"datasets>=2.0.0\",\n  \"pandas>=2.0.0\",\n  \"diff-match-patch>=20200713\",\n  \"hvac>=2.0.0\",\n]\nauth = [\n  \"python-jose[cryptography]>=3.3.0\",\n  \"httpx>=0.25.0\",\n  \"python-ldap>=3.4.0\",\n]\ndev = [\n    \"mypy>=1.0.0\",\n    \"ruff>=0.1.0\",\n    \"setuptools_scm>=10.0.0\",\n]\ndoc = [\n    \"sphinx>=7.0.0\",\n    \"sphinx-rtd-theme>=1.3.0\",\n    \"myst-parser>=2.0.0\",\n]\neval = [\n    \"ragas>=0.1.0\",\n    \"datasets>=2.0.0\",\n    \"pandas>=2.0.0\",\n]\ngemini = [\n    \"google-genai>=1.39.0\",\n]\ngemini-async = [\n    \"google-genai>=1.39.0\",\n    \"anyio>=4.0.0\",\n]\nocr = [\n    \"pytesseract>=0.3.10\",\n]\nbuild = [\n    \"setuptools>=61.0\",\n    \"setuptools-scm>=8.0\",\n    \"cmake>=3.15\",\n    \"wheel\",\n    \"build\",\n]\n# vikingbot - all features included\nbot = [\n  \"pydantic-settings>=2.0.0\",\n  \"websockets>=12.0\",\n  \"websocket-client>=1.6.0\",\n  \"httpx[socks]>=0.25.0\",\n  \"readability-lxml>=0.8.0\",\n  \"rich>=13.0.0\",\n  \"croniter>=2.0.0\",\n  \"socksio>=1.0.0\",\n  \"python-socketio>=5.16.2\",\n  \"python-engineio>=4.13.2\",\n  \"msgpack>=1.0.8\",\n  \"numpy>=1.26.0\",\n  \"python-socks[asyncio]>=2.4.0\",\n  \"prompt-toolkit>=3.0.0\",\n  \"pygments>=2.16.0\",\n  \"html2text>=2020.1.16\",\n  \"beautifulsoup4>=4.12.0\",\n  \"ddgs>=9.0.0\",\n  \"tavily-python>=0.5.0\",\n  \"py-machineid>=1.0.0\",\n  \"mcp>=1,<2\",\n  # All optional features included by default\n  \"langfuse>=3.0.0\",\n  \"python-telegram-bot[socks]>=21.0\",\n  \"lark-oapi>=1.0.0\",\n  \"dingtalk-stream>=0.4.0\",\n  \"slack-sdk>=3.26.0\",\n  \"qq-botpy>=1.0.0\",\n  \"opensandbox>=0.1.5\",\n  \"opensandbox-server>=0.1.6\",\n  \"agent-sandbox>=0.0.23\",\n  \"fusepy>=3.0.1\",\n  \"opencode-ai>=0.1.0a0\",\n  # Auth dependencies\n  \"python-jose[cryptography]>=3.3.0\",\n]\nbenchmark = [\n    \"langchain>=1.0.0\",\n    \"langchain-core>=1.0.0\",\n    \"langchain-openai>=1.0.0\",\n    \"tiktoken>=0.5.0\",\n    \"datasets>=2.0.0\",\n    \"pandas>=2.0.0\",\n    \"python-docx>=1.0.0\",\n]\nlocal-embed = [\n    \"llama-cpp-python>=0.3.0\",\n]\n\nopengauss = [\n  # PostgreSQL wire-compatible driver verified against openGauss DataVec 7.0.\n  \"psycopg2-binary>=2.9,<3\",\n]\n\n[project.urls]\nHomepage = \"https://github.com/volcengine/openviking\"\nDocumentation = \"https://openviking.ai\"\nRepository = \"https://github.com/volcengine/openviking\"\nIssues = \"https://github.com/volcengine/openviking/issues\"\n\n[project.scripts]\nov = \"openviking_cli.rust_cli:main\"  # Rust CLI 入口（极简包装器）\nopenviking = \"openviking_cli.rust_cli:main\"  # Rust CLI 入口（放弃 python CLI）\nopenviking-server = \"openviking_cli.server_bootstrap:main\"  # also: `openviking-server ingest ...`\nopenviking-gateway = \"openviking_gateway.cli:main\"\nvikingbot = \"vikingbot.cli.commands:app\"\n\n[tool.setuptools_scm]\nwrite_to = \"openviking/_version.py\"\nlocal_scheme = \"no-local-version\"\ntag_regex = \"^v(?P<version>[0-9]+(?:\\\\.[0-9]+)*)$\"\ngit_describe_command = \"git describe --dirty --tags --long --match v[0-9]*\"\n\n[tool.setuptools.packages.find]\nwhere = [\".\", \"bot\"]\ninclude = [\"openviking*\", \"vikingbot*\"]\nexclude = [\"tests*\", \"docs*\", \"examples*\"]\n\n[tool.setuptools.package-data]\nopenviking_gateway = [\"client-rules.json\", \"lua/*.lua\"]\n\"openviking.scheduling.expiry\" = [\"lua/*.lua\"]\n\"vikingbot.studio.providers.feishu\" = [\"icon.png\"]\nopenviking = [\n    \"prompts/templates/**/*.yaml\",\n    \"system_assets/**/*\",\n    \"server/static/**/*\",\n    \"web_studio/dist/**/*\",\n    \"lib/ragfs_python*.so\",\n    \"lib/ragfs_python*.pyd\",\n    \"bin/ov\",\n    \"bin/ov.exe\",\n    \"server/account_stores/sql/*.sql\",\n    \"server/account_stores/sql/changes/*.sql\",\n    \"service/sql/*.sql\",\n    \"service/sql/changes/*.sql\",\n    \"storage/vectordb/engine/*.abi3.so\",\n    \"storage/vectordb/engine/*.pyd\",\n]\nvikingbot = [\n    \"**/*.mjs\",\n    \"skills/**/*.md\",\n    \"skills/**/*.sh\",\n    \"workspace/**/*\",\n    \"bridge/**/*\",\n]\n\n[tool.mypy]\npython_version = \"3.10\"\nwarn_return_any = false\nwarn_unused_configs = true\ndisallow_untyped_defs = false\ndisallow_incomplete_defs = false\ncheck_untyped_defs = true\nno_implicit_optional = false\nwarn_redundant_casts = true\nwarn_unused_ignores = true\nignore_missing_imports = true\n\n[tool.pytest.ini_options]\ntestpaths = [\"tests\"]\npython_files = [\"test_*.py\"]\npython_classes = [\"Test*\"]\npython_functions = [\"test_*\"]\nasyncio_mode = \"auto\"\nnorecursedirs = [\"api_test\", \"oc2ov_test\"]\nmarkers = [\n    \"integration: tests that require external services or real model configuration\",\n    \"cli_remote: tests that require a remote OpenViking CLI binary and server connection\",\n]\naddopts = \"-v --cov=openviking --cov-report=term-missing\"\n\n[tool.ruff]\nline-length = 100\nexclude = [\"third_party\"]\ntarget-version = \"py310\"\n\n[tool.ruff.lint]\nselect = [\n    \"E\",  # pycodestyle errors\n    \"W\",  # pycodestyle warnings\n    \"F\",  # pyflakes\n    \"I\",  # isort\n    \"C\",  # flake8-comprehensions\n    \"B\",  # flake8-bugbear\n]\nignore = [\n    \"E501\",  # line too long (handled by black)\n    \"B008\",  # do not perform function calls in argument defaults\n    \"C901\",  # too complex\n    \"B006\",  # Do not use mutable data structures for argument defaults\n    \"B904\",  # Within an `except` clause, raise exceptions with `raise ... from err`\n    \"E741\",  # Ambiguous variable name\n    \"E722\",  # Do not use bare `except`\n    \"B027\",  # empty method in an abstract base class\n]\n\n[tool.ruff.lint.per-file-ignores]\n\"__init__.py\" = [\"F401\"]  # Allow unused imports in __init__.py\n\n[tool.ruff.format]\nquote-style = \"double\"\nindent-style = \"space\"\nskip-magic-trailing-comma = false\nline-ending = \"auto\"\n\n[dependency-groups]\ndev = [\n    \"pytest>=9.0.2\",\n]\n"
